	/** 主 Overlay Widget 实例（游戏内 HUD，显示生命值、法力值等） */","new_string":"private:
	/**
	 * 懒加载 WidgetController 的通用模板辅助函数
	 * 若 Controller 为空则创建、初始化并绑定回调，否则直接返回缓存实例
	 * @param Controller 缓存的控制器引用（TObjectPtr，首次调用后被填充）
	 * @param ControllerClass 要创建的控制器类
	 * @param WCParams WidgetController 初始化参数
	 * @return 已初始化的 WidgetController 实例
	 */
	template<typename T>
	T* GetOrCreateWidgetController(TObjectPtr<T>& Controller, TSubclassOf<T> ControllerClass, const FWidgetControllerParams& WCParams)
	{
		if (Controller == nullptr)
		{
			Controller = NewObject<T>(this, ControllerClass);
			Controller->SetWidgetControllerParams(WCParams);
			Controller->BindCallbacksToDependencies();
		}
		return Controller;
	}

	/** 主 Overlay Widget 实例（游戏内 HUD，显示生命值、法力值等） */"}],"apply_mode":"apply_only"}},"timestamp":1776570736,"type":"TOOL_CALL_ARGS"}

{"rawEvent":{"message_id":"019da3ddd45978bea194c50fb150eb49","conversation_id":"019cec84512077ba9b201d16c8fe025f","tool_call_id":"tooluse_bxJH5wc8F48ltNiSDvn2RT","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/UI/HUD/AuraHUD.cpp","sub_content":"AuraHUD.cpp","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/UI/HUD/AuraHUD.cpp","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Private/UI/HUD/AuraHUD.cpp","multi_replace_content":[{"old_string":"/**
 * 获取或创建 Overlay WidgetController（覆盖层 UI 控制器）
 * 
 * 实现流程：
 * 1. 如果控制器未创建，创建新的 OverlayWidgetController 对象
 * 2. 设置 WidgetController 参数（PC、PS、ASC、AS）
 * 3. 绑定回调到依赖项（属性变化、技能变化等）
 * 4. 返回控制器（单例模式，确保只有一个实例）
 * 
 * @param WCParams WidgetController 参数结构体
 * @return OverlayWidgetController 指针
 * 
 * 使用场景：
 * - 初始化覆盖层 UI 时调用
 * - 由 AuraAbilitySystemLibrary::GetOverlayWidgetController 调用
 * 
 * 注意：
 * - 使用单例模式，确保整个游戏只有一个 OverlayWidgetController
 * - BindCallbacksToDependencies 会绑定所有属性变化回调
 */
UOverlayWidgetController* AAuraHUD::GetOverlayWidgetController(const FWidgetControllerParams& WCParams)
{
	if (OverlayWidgetController == nullptr)
	{
		OverlayWidgetController = NewObject<UOverlayWidgetController>(this, OverlayWidgetControllerClass);
		OverlayWidgetController->SetWidgetControllerParams(WCParams);
		OverlayWidgetController->BindCallbacksToDependencies();
	}
	return OverlayWidgetController;
}

/**
 * 获取或创建 AttributeMenu WidgetController（属性菜单控制器）
 * 
 * 实现流程：
 * 1. 如果控制器未创建，创建新的 AttributeMenuWidgetController 对象
 * 2. 设置 WidgetController 参数
 * 3. 绑定回调到依赖项
 * 4. 返回控制器（单例模式）
 * 
 * @param WCParams WidgetController 参数结构体
 * @return AttributeMenuWidgetController 指针
 * 
 * 使用场景：
 * - 打开属性菜单时调用
 */
UAttributeMenuWidgetController* AAuraHUD::GetAttributeMenuWidgetController(const FWidgetControllerParams& WCParams)
{
	if (AttributeMenuWidgetController == nullptr)
	{
		AttributeMenuWidgetController = NewObject<UAttributeMenuWidgetController>(this, AttributeMenuWidgetControllerClass);
		AttributeMenuWidgetController->SetWidgetControllerParams(WCParams);
		AttributeMenuWidgetController->BindCallbacksToDependencies();
	}
	return AttributeMenuWidgetController;
}

/**
 * 获取或创建 SpellMenu WidgetController（技能菜单控制器）
 * 
 * 实现流程：
 * 1. 如果控制器未创建，创建新的 SpellMenuWidgetController 对象
 * 2. 设置 WidgetController 参数
 * 3. 绑定回调到依赖项
 * 4. 返回控制器（单例模式）
 * 
 * @param WCParams WidgetController 参数结构体
 * @return SpellMenuWidgetController 指针
 * 
 * 使用场景：
 * - 打开技能菜单时调用
 */
USpellMenuWidgetController* AAuraHUD::GetSpellMenuWidgetController(const FWidgetControllerParams& WCParams)
{
	if (SpellMenuWidgetController == nullptr)
	{
		SpellMenuWidgetController = NewObject<USpellMenuWidgetController>(this, SpellMenuWidgetControllerClass);
		SpellMenuWidgetController->SetWidgetControllerParams(WCParams);
		SpellMenuWidgetController->BindCallbacksToDependencies();
	}
	return SpellMenuWidgetController;
}","new_string":"UOverlayWidgetController* AAuraHUD::GetOverlayWidgetController(const FWidgetControllerParams& WCParams)
{
	return GetOrCreateWidgetController(OverlayWidgetController, OverlayWidgetControllerClass, WCParams);
}

UAttributeMenuWidgetController* AAuraHUD::GetAttributeMenuWidgetController(const FWidgetControllerParams& WCParams)
{
	return GetOrCreateWidgetController(AttributeMenuWidgetController, AttributeMenuWidgetControllerClass, WCParams);
}

USpellMenuWidgetController* AAuraHUD::GetSpellMenuWidgetController(const FWidgetControllerParams& WCParams)
{
	return GetOrCreateWidgetController(SpellMenuWidgetController, SpellMenuWidgetControllerClass, WCParams);
}"}],"apply_mode":"apply_only"}},"timestamp":1776570747,"type":"TOOL_CALL_ARGS"}

