#pragma once

#include "CoreMinimal.h"
#include "AbilitySystemInterface.h"
#include "GameFramework/Character.h"
#include "AbilitySystem/Data/CharacterClassInfo.h"
#include "Interaction/CombatInterface.h"
#include "AuraCharacterBase.generated.h"

class UPassiveNiagaraComponent;
class UDebuffNiagaraComponent;
class UNiagaraSystem;
class UAbilitySystemComponent;
class UAttributeSet;
class UGameplayEffect;
class UGameplayAbility;
class UAnimMontage;

/**
 * 所有 Aura 角色的抽象基类（玩家角色与敌人角色均继承自此类）
 *
 * 职责：
 * - 持有并初始化 AbilitySystemComponent（ASC）和 AttributeSet
 * - 实现 ICombatInterface 战斗接口的通用逻辑（死亡、受击、插槽位置等）
 * - 管理角色的 Debuff 特效（燃烧、眩晕）和被动技能特效（光环）
 * - 提供溶解死亡动画的蓝图事件接口
 *
 * 使用示例：
 * // 子类在 PossessedBy 或 BeginPlay 中调用 InitAbilityActorInfo() 完成 ASC 初始化
 * // 然后调用 InitializeDefaultAttributes() 应用默认属性 GE
 * // 最后调用 AddCharacterAbilities() 赋予初始技能
 */
UCLASS(Abstract)
class AURA_API AAuraCharacterBase : public ACharacter, public IAbilitySystemInterface, public ICombatInterface
{
	GENERATED_BODY()

public:
	AAuraCharacterBase();
	virtual void Tick(float DeltaTime) override;

	/** 注册需要网络同步的属性（bIsStunned、bIsBurned、bIsBeingShocked） */
	virtual void GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const;

	/** 重写 TakeDamage，用于处理来自 GAS 之外的伤害（通常不走此路径，GAS 走 AttributeSet） */
	virtual float TakeDamage(float DamageAmount, FDamageEvent const& DamageEvent, AController* EventInstigator, AActor* DamageCauser) override;

	/** 实现 IAbilitySystemInterface，返回角色持有的 ASC */
	virtual UAbilitySystemComponent* GetAbilitySystemComponent() const override;

	/** 获取角色的属性集（AttributeSet） */
	UAttributeSet* GetAttributeSet() const { return AttributeSet; }

	/** ======================== Combat Interface 实现 ======================== */

	/** 返回受击动画蒙太奇 */
	virtual UAnimMontage* GetHitReactMontage_Implementation() override;

	/**
	 * 角色死亡处理
	 * @param DeathImpulse 死亡时施加的物理冲量方向与大小，用于击飞效果
	 */
	virtual void Die(const FVector& DeathImpulse) override;

	/** 返回死亡委托引用，外部可绑定死亡回调 */
	virtual FOnDeathSignature& GetOnDeathDelegate() override;

	/**
	 * 根据 MontageTag 返回对应的战斗插槽世界位置（如武器尖端、左手、右手等）
	 * @param MontageTag 标识插槽类型的 GameplayTag
	 */
	virtual FVector GetCombatSocketLocation_Implementation(const FGameplayTag& MontageTag) override;

	/** 返回角色是否已死亡 */
	virtual bool IsDead_Implementation() const override;

	/** 返回角色的 Avatar Actor（即自身） */
	virtual AActor* GetAvatar_Implementation() override;

	/** 返回所有带标签的攻击蒙太奇数组 */
	virtual TArray<FTaggedMontage> GetAttackMontages_Implementation() override;

	/** 返回死亡时播放的血液 Niagara 特效 */
	virtual UNiagaraSystem* GetBloodEffect_Implementation() override;

	/**
	 * 根据 MontageTag 查找并返回对应的 FTaggedMontage 结构体
	 * @param MontageTag 要查找的标签
	 */
	virtual FTaggedMontage GetTaggedMontageByTag_Implementation(const FGameplayTag& MontageTag) override;

	/** 返回当前召唤物数量 */
	virtual int32 GetMinionCount_Implementation() override;

	/**
	 * 增加/减少召唤物计数
	 * @param Amount 正数增加，负数减少
	 */
	virtual void IncremenetMinionCount_Implementation(int32 Amount) override;

	/** 返回角色职业类型（战士、法师、游侠等） */
	virtual ECharacterClass GetCharacterClass_Implementation() override;

	/** 返回 ASC 注册完成委托的引用，供外部监听 ASC 初始化完成事件 */
	virtual FOnASCRegistered& GetOnASCRegisteredDelegate() override;

	/** 返回武器骨骼网格体组件 */
	virtual USkeletalMeshComponent* GetWeapon_Implementation() override;

	/**
	 * 设置角色是否正在被电击（Shock 状态）
	 * @param bInShock true 表示进入电击状态，false 表示退出
	 */
	virtual void SetIsBeingShocked_Implementation(bool bInShock) override;

	/** 返回角色当前是否处于电击状态 */
	virtual bool IsBeingShocked_Implementation() const override;

	/** 返回受到伤害时的委托引用，可用于绑定伤害数值显示等回调 */
	virtual FOnDamageSignature& GetOnDamageSignature() override;

	/** ======================== end Combat Interface ======================== */

	/** ASC 注册完成时广播（服务器和客户端均会触发） */
	FOnASCRegistered OnAscRegistered;

	/** 角色死亡时广播 */
	FOnDeathSignature OnDeathDelegate;

	/** 角色受到伤害时广播，携带伤害数值 */
	FOnDamageSignature OnDamageDelegate;

	/**
	 * 多播 RPC：在所有客户端上执行死亡逻辑（布娃娃、溶解特效、死亡音效等）
	 * @param DeathImpulse 死亡冲量，用于布娃娃物理
	 */
	UFUNCTION(NetMulticast, Reliable)
	virtual void MulticastHandleDeath(const FVector& DeathImpulse);

	/**
	 * 带标签的攻击蒙太奇数组
	 * 每个元素包含一个 AnimMontage 和对应的 GameplayTag（用于标识攻击类型和插槽）
	 * 在蓝图或 Details 面板中配置
	 */
	UPROPERTY(EditAnywhere, Category = "Combat")
	TArray<FTaggedMontage> AttackMontages;

	/** 是否处于眩晕状态（网络同步，变化时触发 OnRep_Stunned） */
	UPROPERTY(ReplicatedUsing=OnRep_Stunned, BlueprintReadOnly)
	bool bIsStunned = false;

	/** 是否处于燃烧状态（网络同步，变化时触发 OnRep_Burned） */
	UPROPERTY(ReplicatedUsing=OnRep_Burned, BlueprintReadOnly)
	bool bIsBurned = false;

	/** 是否正在被电击（网络同步，由 SetIsBeingShocked_Implementation 控制） */
	UPROPERTY(Replicated, BlueprintReadOnly)
	bool bIsBeingShocked = false;

	/** 眩晕状态同步回调：在客户端更新眩晕特效和移动速度 */
	UFUNCTION()
	virtual void OnRep_Stunned();

	/** 燃烧状态同步回调：在客户端更新燃烧特效 */
	UFUNCTION()
	virtual void OnRep_Burned();

	/** 设置角色职业类型（通常由 SpawnPoint 在生成时调用） */
	void SetCharacterClass(ECharacterClass InClass) { CharacterClass = InClass; }

protected:
	virtual void BeginPlay() override;

	/**
	 * 武器骨骼网格体
	 * 挂载在角色骨骼的武器插槽上，用于显示武器模型和提供战斗插槽位置
	 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Combat")
	TObjectPtr<USkeletalMeshComponent> Weapon;

	/** 武器尖端插槽名称（用于投射物生成位置） */
	UPROPERTY(EditAnywhere, Category = "Combat")
	FName WeaponTipSocketName;

	/** 左手插槽名称（用于近战左手攻击位置） */
	UPROPERTY(EditAnywhere, Category = "Combat")
	FName LeftHandSocketName;

	/** 右手插槽名称（用于近战右手攻击位置） */
	UPROPERTY(EditAnywhere, Category = "Combat")
	FName RightHandSocketName;

	/** 尾部插槽名称（用于特殊怪物的尾部攻击位置） */
	UPROPERTY(EditAnywhere, Category = "Combat")
	FName TailSocketName;

	/** 角色是否已死亡（本地标记，不参与网络同步，由 MulticastHandleDeath 设置） */
	UPROPERTY(BlueprintReadOnly)
	bool bDead = false;

	/**
	 * 眩晕标签变化回调
	 * 当 ASC 上的眩晕 GameplayTag 数量发生变化时调用
	 * @param CallbackTag 触发回调的标签
	 * @param NewCount 当前标签数量（0 表示眩晕结束，>0 表示眩晕中）
	 */
	virtual void StunTagChanged(const FGameplayTag CallbackTag, int32 NewCount);

	/** 基础行走速度（眩晕时会被设为 0，恢复时还原此值） */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Combat")
	float BaseWalkSpeed = 600.f;

	/** 能力系统组件（GAS 核心，管理技能、属性、效果） */
	UPROPERTY()
	TObjectPtr<UAbilitySystemComponent> AbilitySystemComponent;

	/** 属性集（存储所有 GameplayAttribute，如生命值、法力值、攻击力等） */
	UPROPERTY()
	TObjectPtr<UAttributeSet> AttributeSet;

	/**
	 * 初始化 AbilityActorInfo
	 * 玩家角色在 PossessedBy/OnRep_PlayerState 中调用，敌人在 BeginPlay 中调用
	 * 必须在 ASC 可用后立即调用，否则技能无法正常工作
	 */
	virtual void InitAbilityActorInfo();

	/** 主要属性初始化 GameplayEffect（力量、智力、韧性、活力） */
	UPROPERTY(BlueprintReadOnly, EditAnywhere, Category = "Attributes")
	TSubclassOf<UGameplayEffect> DefaultPrimaryAttributes;

	/** 次要属性初始化 GameplayEffect（护甲、暴击率、格挡率等，由主属性派生） */
	UPROPERTY(BlueprintReadOnly, EditAnywhere, Category = "Attributes")
	TSubclassOf<UGameplayEffect> DefaultSecondaryAttributes;

	/** 生命值/法力值初始化 GameplayEffect（将 Health/Mana 设为最大值） */
	UPROPERTY(BlueprintReadOnly, EditAnywhere, Category = "Attributes")
	TSubclassOf<UGameplayEffect> DefaultVitalAttributes;

	/**
	 * 将指定 GameplayEffect 应用到自身
	 * @param GameplayEffectClass 要应用的 GE 类
	 * @param Level 应用时使用的等级（影响 ScalableFloat 曲线取值）
	 */
	void ApplyEffectToSelf(TSubclassOf<UGameplayEffect> GameplayEffectClass, float Level) const;

	/**
	 * 按顺序应用三组默认属性 GE（主属性 → 次属性 → 生命/法力）
	 * 子类可重写以实现不同的初始化逻辑（如从存档加载）
	 */
	virtual void InitializeDefaultAttributes() const;

	/** 从 StartupAbilities 和 StartupPassiveAbilities 数组赋予角色初始技能 */
	void AddCharacterAbilities();

	/* ======================== 溶解死亡特效 ======================== */

	/** 触发角色身体和武器的溶解动画 */
	void Dissolve();

	/**
	 * 蓝图事件：启动角色身体溶解时间轴
	 * @param DynamicMaterialInstance 动态材质实例，蓝图中通过修改其参数驱动溶解效果
	 */
	UFUNCTION(BlueprintImplementableEvent)
	void StartDissolveTimeline(UMaterialInstanceDynamic* DynamicMaterialInstance);

	/**
	 * 蓝图事件：启动武器溶解时间轴
	 * @param DynamicMaterialInstance 武器的动态材质实例
	 */
	UFUNCTION(BlueprintImplementableEvent)
	void StartWeaponDissolveTimeline(UMaterialInstanceDynamic* DynamicMaterialInstance);

	/** 角色身体溶解材质（需要包含溶解参数的材质实例） */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	TObjectPtr<UMaterialInstance> DissolveMaterialInstance;

	/** 武器溶解材质 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	TObjectPtr<UMaterialInstance> WeaponDissolveMaterialInstance;

	/** 死亡时播放的血液/受击 Niagara 粒子特效 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Combat")
	UNiagaraSystem* BloodEffect;

	/** 死亡时播放的音效 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Combat")
	USoundBase* DeathSound;

	/* ======================== 召唤物管理 ======================== */

	/** 当前存活的召唤物数量（由 IncremenetMinionCount_Implementation 维护） */
	int32 MinionCount = 0;

	/**
	 * 角色职业类型（默认为战士）
	 * 决定初始属性曲线、可用技能列表和 XP 奖励
	 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Character Class Defaults")
	ECharacterClass CharacterClass = ECharacterClass::Warrior;

	/** 燃烧 Debuff Niagara 组件（当 bIsBurned 为 true 时激活） */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UDebuffNiagaraComponent> BurnDebuffComponent;

	/** 眩晕 Debuff Niagara 组件（当 bIsStunned 为 true 时激活） */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UDebuffNiagaraComponent> StunDebuffComponent;

private:

	/**
	 * 初始主动技能列表
	 * 在 AddCharacterAbilities() 中赋予角色，通常包含攻击、技能等主动能力
	 */
	UPROPERTY(EditAnywhere, Category = "Abilities")
	TArray<TSubclassOf<UGameplayAbility>> StartupAbilities;

	/**
	 * 初始被动技能列表
	 * 在 AddCharacterAbilities() 中赋予角色，持续生效的被动效果（如光环、生命恢复等）
	 */
	UPROPERTY(EditAnywhere, Category = "Abilities")
	TArray<TSubclassOf<UGameplayAbility>> StartupPassiveAbilities;

	/** 受击动画蒙太奇（被攻击时播放的反应动画） */
	UPROPERTY(EditAnywhere, Category = "Combat")
	TObjectPtr<UAnimMontage> HitReactMontage;

	/** 被动技能"保护光环"的 Niagara 组件（装备对应被动技能时激活） */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UPassiveNiagaraComponent> HaloOfProtectionNiagaraComponent;

	/** 被动技能"生命虹吸"的 Niagara 组件 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UPassiveNiagaraComponent> LifeSiphonNiagaraComponent;

	/** 被动技能"法力虹吸"的 Niagara 组件 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UPassiveNiagaraComponent> ManaSiphonNiagaraComponent;

	/** 所有被动特效 Niagara 组件的挂载根节点（跟随角色移动但不随骨骼旋转） */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<USceneComponent> EffectAttachComponent;
};
"}

{"rawEvent":{"message_id":"019cbbb199bf7c819b045efcd483bbb6","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_Zt2r425gD04HtqJ9lUXnde","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/Character/AuraCharacter.h","sub_content":"AuraCharacter.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/Character/AuraCharacter.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/Character/AuraCharacter.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "Character/AuraCharacterBase.h"
#include "Interaction/PlayerInterface.h"
#include "AuraCharacter.generated.h"

class UNiagaraComponent;
class UCameraComponent;
class USpringArmComponent;

/**
 * 玩家控制的 Aura 角色类
 *
 * 职责：
 * - 继承 AAuraCharacterBase，额外实现 IPlayerInterface（玩家专属接口）
 * - 管理摄像机（弹簧臂 + 俯视摄像机）
 * - 处理玩家等级提升、XP 获取、属性点/技能点分配
 * - 管理存档进度的加载与保存
 * - 在服务端（PossessedBy）和客户端（OnRep_PlayerState）分别初始化 ASC
 *
 * 网络说明：
 * - ASC 和 AttributeSet 存储在 PlayerState 上（跨关卡持久化）
 * - PossessedBy：服务端初始化 ASC ActorInfo 并赋予技能
 * - OnRep_PlayerState：客户端初始化 ASC ActorInfo
 */
UCLASS()
class AURA_API AAuraCharacter : public AAuraCharacterBase, public IPlayerInterface
{
	GENERATED_BODY()
public:
	AAuraCharacter();

	/** 服务端：角色被控制器接管时调用，初始化 ASC 并赋予初始技能 */
	virtual void PossessedBy(AController* NewController) override;

	/** 客户端：PlayerState 同步完成后调用，初始化客户端侧的 ASC ActorInfo */
	virtual void OnRep_PlayerState() override;

	/** ======================== Player Interface 实现 ======================== */

	/**
	 * 增加经验值
	 * @param InXP 要增加的 XP 数量
	 */
	virtual void AddToXP_Implementation(int32 InXP) override;

	/** 触发升级逻辑（播放升级特效、分配属性点和技能点） */
	virtual void LevelUp_Implementation() override;

	/** 返回当前 XP 总量 */
	virtual int32 GetXP_Implementation() const override;

	/**
	 * 根据 XP 数量反查对应的等级
	 * @param InXP 要查询的 XP 值
	 * @return 对应的角色等级
	 */
	virtual int32 FindLevelForXP_Implementation(int32 InXP) const override;

	/**
	 * 获取指定等级升级时奖励的属性点数量
	 * @param Level 目标等级
	 */
	virtual int32 GetAttributePointsReward_Implementation(int32 Level) const override;

	/**
	 * 获取指定等级升级时奖励的技能点数量
	 * @param Level 目标等级
	 */
	virtual int32 GetSpellPointsReward_Implementation(int32 Level) const override;

	/**
	 * 增加玩家等级
	 * @param InPlayerLevel 要增加的等级数
	 */
	virtual void AddToPlayerLevel_Implementation(int32 InPlayerLevel) override;

	/**
	 * 增加属性点
	 * @param InAttributePoints 要增加的属性点数
	 */
	virtual void AddToAttributePoints_Implementation(int32 InAttributePoints) override;

	/**
	 * 增加技能点
	 * @param InSpellPoints 要增加的技能点数
	 */
	virtual void AddToSpellPoints_Implementation(int32 InSpellPoints) override;

	/** 返回当前可用属性点数量 */
	virtual int32 GetAttributePoints_Implementation() const override;

	/** 返回当前可用技能点数量 */
	virtual int32 GetSpellPoints_Implementation() const override;

	/**
	 * 在地面显示魔法圆圈（用于需要指定目标位置的技能）
	 * @param DecalMaterial 圆圈使用的贴花材质（可为 nullptr 使用默认材质）
	 */
	virtual void ShowMagicCircle_Implementation(UMaterialInterface* DecalMaterial) override;

	/** 隐藏魔法圆圈 */
	virtual void HideMagicCircle_Implementation() override;

	/**
	 * 保存游戏进度到存档
	 * @param CheckpointTag 触发保存的检查点标签，用于记录重生位置
	 */
	virtual void SaveProgress_Implementation(const FName& CheckpointTag) override;

	/** ======================== end Player Interface ======================== */

	/** ======================== Combat Interface 重写 ======================== */

	/** 返回玩家当前等级（从 PlayerState 获取） */
	virtual int32 GetPlayerLevel_Implementation() override;

	/**
	 * 玩家死亡处理（重写基类）
	 * 额外逻辑：启动死亡计时器，倒计时结束后重新加载关卡
	 * @param DeathImpulse 死亡冲量
	 */
	virtual void Die(const FVector& DeathImpulse) override;

	/** ======================== end Combat Interface ======================== */

	/**
	 * 死亡后自动重生/重载的等待时间（秒）
	 * 默认 5 秒，可在蓝图 Details 面板中调整
	 */
	UPROPERTY(EditDefaultsOnly)
	float DeathTime = 5.f;

	/** 死亡计时器句柄，用于在 DeathTime 后触发重生逻辑 */
	FTimerHandle DeathTimer;

	/**
	 * 升级特效 Niagara 组件
	 * 升级时在角色位置播放粒子特效（多播 RPC 触发）
	 */
	UPROPERTY(VisibleAnywhere, BlueprintReadOnly)
	TObjectPtr<UNiagaraComponent> LevelUpNiagaraComponent;

	/** 眩晕状态同步回调（重写基类，额外处理玩家输入禁用） */
	virtual void OnRep_Stunned() override;

	/** 燃烧状态同步回调（重写基类） */
	virtual void OnRep_Burned() override;

	/** 从存档加载玩家进度（属性、技能、等级、XP 等） */
	void LoadProgress();

private:
	/**
	 * 俯视摄像机组件
	 * 提供游戏的俯视角视角，挂载在 CameraBoom 末端
	 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UCameraComponent> TopDownCameraComponent;

	/**
	 * 弹簧臂组件
	 * 控制摄像机与角色的距离和角度，支持碰撞缩短
	 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<USpringArmComponent> CameraBoom;

	/**
	 * 初始化 ASC ActorInfo（重写基类）
	 * 玩家角色的 ASC 在 PlayerState 上，需要从 PlayerState 获取
	 */
	virtual void InitAbilityActorInfo() override;

	/**
	 * 多播 RPC：在所有客户端播放升级粒子特效
	 * 升级时由服务端调用，确保所有玩家都能看到升级特效
	 */
	UFUNCTION(NetMulticast, Reliable)
	void MulticastLevelUpParticles() const;
};
