	TargetingEnemy, // 鼠标悬停在敌人上（显示攻击光标，点击触发攻击）
	TargetingNonEnemy, // 鼠标悬停在非敌人可交互对象上
	NotTargeting // 鼠标悬停在地面或无效目标上（点击触发自动寻路移动）
};

