	 * 由服务端调用，在本地客户端生成 DamageTextComponent
	 * @param DamageAmount 伤害数值
	 * @param TargetCharacter 受伤角色（用于确定显示位置）
	 * @param bBlockedHit 是否为格挡命中（显示不同颜色/样式）
	 * @param bCriticalHit 是否为暴击（显示不同颜色/样式）
	 */
	UFUNCTION(Client, Reliable)
	void ShowDamageNumber(float DamageAmount, ACharacter* TargetCharacter, bool bBlockedHit, bool bCriticalHit);

	/**
	 * 在地面显示魔法圆圈（蓝图可调用）
	 * 生成 MagicCircle Actor 并跟随鼠标位置移动
	 * @param DecalMaterial 圆圈贴花材质（nullptr 使用默认材质）
	 */
	UFUNCTION(BlueprintCallable)
	void ShowMagicCircle(UMaterialInterface* DecalMaterial = nullptr);

	/** 隐藏并销毁魔法圆圈（蓝图可调用） */
	UFUNCTION(BlueprintCallable)
	void HideMagicCircle();

protected:
	virtual void BeginPlay() override;

	/** 设置输入组件：绑定移动、Shift 键和技能输入 */
	virtual void SetupInputComponent() override;

private:
	/**
	 * 增强输入映射上下文
	 * 包含所有 Aura 游戏的输入映射（移动、技能等）
	 */
	UPROPERTY(EditAnywhere, Category="Input")
	TObjectPtr<UInputMappingContext> AuraContext;

	/** 移动输入动作（WASD 或鼠标点击移动） */
	UPROPERTY(EditAnywhere, Category="Input")
	TObjectPtr<UInputAction> MoveAction;

	/** Shift 键输入动作（按住 Shift 时强制移动而不攻击） */
	UPROPERTY(EditAnywhere, Category="Input")
	TObjectPtr<UInputAction> ShiftAction;

	/** Shift 键按下回调 */
	void ShiftPressed() { bShiftKeyDown = true; };

	/** Shift 键释放回调 */
	void ShiftReleased() { bShiftKeyDown = false; };

	/** Shift 键当前是否按下（影响点击行为：按住 Shift 时只移动不攻击） */
	bool bShiftKeyDown = false;

	/**
	 * 处理移动输入
	 * @param InputActionValue 包含移动方向的输入值（2D 轴）
	 */
	void Move(const FInputActionValue& InputActionValue);

	/**
	 * 每帧执行鼠标光标追踪
	 * 通过射线检测确定鼠标下方的 Actor，并更新高亮状态和 TargetingStatus
	 */
	void CursorTrace();

	/** 上一帧鼠标悬停的 Actor（用于取消高亮） */
	TObjectPtr<AActor> LastActor;

	/** 当前帧鼠标悬停的 Actor */
	TObjectPtr<AActor> ThisActor;

	/** 鼠标光标射线检测结果（包含命中位置、法线等信息） */
	FHitResult CursorHit;

	/**
	 * 高亮指定 Actor（调用 IHighlightInterface::HighlightActor）
	 * @param InActor 要高亮的 Actor
	 */
	static void HighlightActor(AActor* InActor);

	/**
	 * 取消高亮指定 Actor（调用 IHighlightInterface::UnHighlightActor）
	 * @param InActor 要取消高亮的 Actor
	 */
	static void UnHighlightActor(AActor* InActor);

	/**
	 * 技能输入按下回调（由 AuraInputComponent 绑定）
	 * @param InputTag 按下的输入标签
	 */
	void AbilityInputTagPressed(FGameplayTag InputTag);

	/**
	 * 技能输入释放回调
	 * @param InputTag 释放的输入标签
	 */
	void AbilityInputTagReleased(FGameplayTag InputTag);

	/**
	 * 技能输入持续按住回调
	 * @param InputTag 持续按住的输入标签
	 */
	void AbilityInputTagHeld(FGameplayTag InputTag);

	/**
	 * 技能输入配置数据资产
	 * 定义每个 InputAction 对应的 GameplayTag（如 LMB → InputTag.LMB）
	 */
	UPROPERTY(EditDefaultsOnly, Category="Input")
	TObjectPtr<UAuraInputConfig> InputConfig;

	/** 缓存的 ASC 引用（避免每帧重复查找） */
	UPROPERTY()
	TObjectPtr<UAuraAbilitySystemComponent> AuraAbilitySystemComponent;

	/** 懒加载获取 ASC（首次调用时从 PlayerState 获取并缓存） */
	UAuraAbilitySystemComponent* GetASC();

	/** 自动寻路的目标位置（鼠标点击时记录，自动寻路时作为终点） */
	FVector CachedDestination = FVector::ZeroVector;

	/** 鼠标按住时间（用于区分短按和长按） */
	float FollowTime = 0.f;

	/** 短按阈值（秒）：按住时间小于此值视为短按，触发点击移动 */
	float ShortPressThreshold = 0.5f;

	/** 是否正在自动寻路移动 */
	bool bAutoRunning = false;

	/** 当前鼠标目标状态（影响点击行为） */
	ETargetingStatus TargetingStatus = ETargetingStatus::NotTargeting;

	/**
	 * 自动寻路到达判定半径（单位：cm）
	 * 角色与目标点距离小于此值时停止自动寻路
	 */
	UPROPERTY(EditDefaultsOnly)
	float AutoRunAcceptanceRadius = 50.f;

	/**
	 * 自动寻路路径样条线
	 * 使用 Navigation Mesh 生成路径后，将路径点存储在此样条线中
	 * 每帧沿样条线方向移动角色
	 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<USplineComponent> Spline;

	/** 点击地面时在目标位置播放的 Niagara 特效（点击反馈） */
	UPROPERTY(EditDefaultsOnly)
	TObjectPtr<UNiagaraSystem> ClickNiagaraSystem;

	/**
	 * 执行自动寻路移动
	 * 每帧计算样条线上最近点的切线方向，并向该方向移动角色
	 */
	void AutoRun();

	/** 浮动伤害数字 Widget 组件类（在 Details 面板中指定） */
	UPROPERTY(EditDefaultsOnly)
	TSubclassOf<UDamageTextComponent> DamageTextComponentClass;

	/** 魔法圆圈 Actor 类（在 Details 面板中指定） */
	UPROPERTY(EditDefaultsOnly)
	TSubclassOf<AMagicCircle> MagicCircleClass;

	/** 当前场景中的魔法圆圈 Actor 实例（ShowMagicCircle 时生成，HideMagicCircle 时销毁） */
	UPROPERTY()
	TObjectPtr<AMagicCircle> MagicCircle;

	/** 每帧更新魔法圆圈位置（跟随鼠标光标在地面的投影位置） */
	void UpdateMagicCircleLocation();
};
"}

{"rawEvent":{"message_id":"019cbbb199bf7c819b045efcd483bbb6","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_vhXm4aoRySYxNJZf5nqC0Z","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/Player/AuraPlayerState.h","sub_content":"AuraPlayerState.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/Player/AuraPlayerState.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/Player/AuraPlayerState.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "AbilitySystemInterface.h"
#include "GameFramework/PlayerState.h"
#include "AuraPlayerState.generated.h"

class UAbilitySystemComponent;
class UAttributeSet;
class ULevelUpInfo;

/** 玩家单一数值属性变化时广播（XP、属性点、技能点） */
DECLARE_MULTICAST_DELEGATE_OneParam(FOnPlayerStatChanged, int32 /*StatValue*/)

/** 玩家等级变化时广播（携带新等级和是否为升级事件） */
DECLARE_MULTICAST_DELEGATE_TwoParams(FOnLevelChanged, int32 /*StatValue*/, bool /*bLevelUp*/)

/**
 * Aura 玩家状态类
 *
 * 职责：
 * - 持有 AbilitySystemComponent 和 AttributeSet（跨关卡持久化）
 * - 存储玩家进度数据：等级、XP、属性点、技能点
 * - 提供数据变化委托，供 UI 系统监听
 *
 * 网络说明：
 * - PlayerState 在服务端和所有客户端上都存在
 * - Level、XP、AttributePoints、SpellPoints 均通过 ReplicatedUsing 同步
 * - ASC 存储在 PlayerState 上，确保跨关卡（无缝旅行）时数据不丢失
 *
 * 使用示例：
 * // 监听 XP 变化（在 WidgetController 中）
 * PlayerState->OnXPChangedDelegate.AddUObject(this, &UMyController::OnXPChanged);
 * // 增加 XP
 * PlayerState->AddToXP(100);
 */
UCLASS()
class AURA_API AAuraPlayerState : public APlayerState, public IAbilitySystemInterface
{
	GENERATED_BODY()
public:
	AAuraPlayerState();

	/** 注册需要网络同步的属性（Level、XP、AttributePoints、SpellPoints） */
	virtual void GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const override;

	/** 实现 IAbilitySystemInterface，返回玩家的 ASC */
	virtual UAbilitySystemComponent* GetAbilitySystemComponent() const override;

	/** 获取属性集 */
	UAttributeSet* GetAttributeSet() const { return AttributeSet; }

	/**
	 * 升级信息数据资产
	 * 定义每个等级所需的 XP 阈值、属性点奖励和技能点奖励
	 * 在 Details 面板中指定
	 */
	UPROPERTY(EditDefaultsOnly)
	TObjectPtr<ULevelUpInfo> LevelUpInfo;

	/** XP 变化时广播（UI 经验条监听此委托） */
	FOnPlayerStatChanged OnXPChangedDelegate;

	/** 等级变化时广播（UI 等级显示监听此委托，bLevelUp=true 时触发升级特效） */
	FOnLevelChanged OnLevelChangedDelegate;

	/** 属性点变化时广播（属性菜单 UI 监听此委托） */
	FOnPlayerStatChanged OnAttributePointsChangedDelegate;

	/** 技能点变化时广播（技能菜单 UI 监听此委托） */
	FOnPlayerStatChanged OnSpellPointsChangedDelegate;

	/** 获取当前等级 */
	FORCEINLINE int32 GetPlayerLevel() const { return Level; }

	/** 获取当前 XP 总量 */
	FORCEINLINE int32 GetXP() const { return XP; }

	/** 获取当前可用属性点数量 */
	FORCEINLINE int32 GetAttributePoints() const { return AttributePoints; }

	/** 获取当前可用技能点数量 */
	FORCEINLINE int32 GetSpellPoints() const { return SpellPoints; }

	/**
	 * 增加 XP（累加到当前值）
	 * @param InXP 要增加的 XP 数量
	 */
	void AddToXP(int32 InXP);

	/**
	 * 增加等级（累加到当前值）
	 * @param InLevel 要增加的等级数
	 */
	void AddToLevel(int32 InLevel);

	/**
	 * 增加属性点（累加到当前值）
	 * @param InPoints 要增加的属性点数
	 */
	void AddToAttributePoints(int32 InPoints);

	/**
	 * 增加技能点（累加到当前值）
	 * @param InPoints 要增加的技能点数
	 */
	void AddToSpellPoints(int32 InPoints);

	/**
	 * 直接设置 XP（用于从存档加载）
	 * @param InXP 要设置的 XP 值
	 */
	void SetXP(int32 InXP);

	/**
	 * 直接设置等级（用于从存档加载）
	 * @param InLevel 要设置的等级
	 */
	void SetLevel(int32 InLevel);

	/**
	 * 直接设置属性点（用于从存档加载）
	 * @param InPoints 要设置的属性点数
	 */
	void SetAttributePoints(int32 InPoints);

	/**
	 * 直接设置技能点（用于从存档加载）
	 * @param InPoints 要设置的技能点数
	 */
	void SetSpellPoints(int32 InPoints);

protected:
	/**
	 * 能力系统组件（存储在 PlayerState 上，跨关卡持久化）
	 * 玩家角色的 ASC 通过 GetAbilitySystemComponent() 返回此组件
	 */
	UPROPERTY(VisibleAnywhere)
	TObjectPtr<UAbilitySystemComponent> AbilitySystemComponent;

	/** 属性集（存储在 PlayerState 上，跨关卡持久化） */
	UPROPERTY()
	TObjectPtr<UAttributeSet> AttributeSet;

private:
	/**
	 * 玩家当前等级（网络同步，变化时触发 OnRep_Level）
	 * 初始值为 1
	 */
	UPROPERTY(VisibleAnywhere, ReplicatedUsing=OnRep_Level)
	int32 Level = 1;

	/**
	 * 玩家当前 XP 总量（网络同步，变化时触发 OnRep_XP）
	 * 初始值为 0
	 */
	UPROPERTY(VisibleAnywhere, ReplicatedUsing=OnRep_XP)
	int32 XP = 0;

	/**
	 * 可用属性点数量（网络同步，变化时触发 OnRep_AttributePoints）
	 * 升级时获得，用于提升主属性
	 */
	UPROPERTY(VisibleAnywhere, ReplicatedUsing=OnRep_AttributePoints)
	int32 AttributePoints = 0;

	/**
	 * 可用技能点数量（网络同步，变化时触发 OnRep_SpellPoints）
	 * 升级时获得，用于解锁/升级技能
	 */
	UPROPERTY(VisibleAnywhere, ReplicatedUsing=OnRep_SpellPoints)
	int32 SpellPoints = 0;

	/**
	 * 等级同步回调：广播 OnLevelChangedDelegate
	 * @param OldLevel 同步前的旧等级
	 */
	UFUNCTION()
	void OnRep_Level(int32 OldLevel);

	/**
	 * XP 同步回调：广播 OnXPChangedDelegate
	 * @param OldXP 同步前的旧 XP 值
	 */
	UFUNCTION()
	void OnRep_XP(int32 OldXP);

	/**
	 * 属性点同步回调：广播 OnAttributePointsChangedDelegate
	 * @param OldAttributePoints 同步前的旧属性点数
	 */
	UFUNCTION()
	void OnRep_AttributePoints(int32 OldAttributePoints);

	/**
	 * 技能点同步回调：广播 OnSpellPointsChangedDelegate
	 * @param OldSpellPoints 同步前的旧技能点数
	 */
	UFUNCTION()
	void OnRep_SpellPoints(int32 OldSpellPoints);
};
