#pragma once

#include "CoreMinimal.h"
#include "AbilitySystemComponent.h"
#include "UObject/NoExportTypes.h"
#include "AuraWidgetController.generated.h"

/** 玩家单一整数属性变化时广播（等级、属性点、技能点等） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnPlayerStatChangedSignature, int32, NewValue);

/** 技能信息变化时广播（技能图标、描述等 UI 数据更新） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FAbilityInfoSignature, const FAuraAbilityInfo&, Info);

class UAttributeSet;
class UAbilitySystemComponent;
class AAuraPlayerController;
class AAuraPlayerState;
class UAuraAbilitySystemComponent;
class UAuraAttributeSet;
class UAbilityInfo;

/**
 * Widget 控制器初始化参数结构体
 * 封装创建 WidgetController 所需的四个核心对象
 *
 * 使用示例：
 * // 在 HUD 中创建 WidgetController 时传入
 * FWidgetControllerParams Params(PlayerController, PlayerState, ASC, AttributeSet);
 * OverlayWidgetController->SetWidgetControllerParams(Params);
 */
USTRUCT(BlueprintType)
struct FWidgetControllerParams
{
	GENERATED_BODY()

	FWidgetControllerParams() {}

	/**
	 * 便捷构造函数
	 * @param PC 玩家控制器
	 * @param PS 玩家状态
	 * @param ASC 能力系统组件
	 * @param AS 属性集
	 */
	FWidgetControllerParams(APlayerController* PC, APlayerState* PS, UAbilitySystemComponent* ASC, UAttributeSet* AS)
	: PlayerController(PC), PlayerState(PS), AbilitySystemComponent(ASC), AttributeSet(AS) {}

	/** 玩家控制器（用于获取输入和本地玩家信息） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite)
	TObjectPtr<APlayerController> PlayerController = nullptr;

	/** 玩家状态（用于获取等级、XP 等进度数据） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite)
	TObjectPtr<APlayerState> PlayerState = nullptr;

	/** 能力系统组件（用于绑定属性变化回调和技能状态监听） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite)
	TObjectPtr<UAbilitySystemComponent> AbilitySystemComponent = nullptr;

	/** 属性集（用于获取具体属性值） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite)
	TObjectPtr<UAttributeSet> AttributeSet = nullptr;
};

/**
 * Aura Widget 控制器基类
 *
 * 职责：
 * - 持有四个核心引用（PC、PS、ASC、AS）
 * - 提供懒加载的 Aura 专用类型转换（GetAuraPC、GetAuraPS 等）
 * - 定义 BroadcastInitialValues 和 BindCallbacksToDependencies 接口
 * - 广播技能信息（BroadcastAbilityInfo）
 *
 * 子类实现模式：
 * 1. 重写 BindCallbacksToDependencies：绑定 ASC/PS 的委托回调
 * 2. 重写 BroadcastInitialValues：广播当前属性值给 Widget 初始化显示
 *
 * 注意：WidgetController 是 UObject，不参与网络同步，只在本地客户端存在
 */
UCLASS()
class AURA_API UAuraWidgetController : public UObject
{
	GENERATED_BODY()
public:
	/**
	 * 设置 Widget 控制器参数（初始化四个核心引用）
	 * 在 HUD 创建 WidgetController 后立即调用
	 * @param WCParams 包含 PC、PS、ASC、AS 的参数结构体
	 */
	UFUNCTION(BlueprintCallable)
	void SetWidgetControllerParams(const FWidgetControllerParams& WCParams);

	/**
	 * 广播初始属性值给 Widget（蓝图可调用）
	 * 在 Widget 初始化时调用，确保 UI 显示正确的初始数据
	 * 子类必须重写此函数以广播各自关心的属性
	 */
	UFUNCTION(BlueprintCallable)
	virtual void BroadcastInitialValues();

	/**
	 * 绑定回调到依赖项（ASC、PS 的委托）
	 * 在 WidgetController 初始化后调用，建立数据变化的监听链
	 * 子类必须重写此函数以绑定各自需要监听的委托
	 */
	virtual void BindCallbacksToDependencies();

	/**
	 * 技能信息广播委托（蓝图可绑定）
	 * 当技能信息更新时广播，Widget 可绑定此委托更新技能图标和描述
	 */
	UPROPERTY(BlueprintAssignable, Category="GAS|Messages")
	FAbilityInfoSignature AbilityInfoDelegate;

	/**
	 * 广播所有技能的信息
	 * 遍历 ASC 中所有已赋予的技能，通过 AbilityInfoDelegate 广播每个技能的 UI 数据
	 * 在 BroadcastInitialValues 中调用，确保技能栏初始显示正确
	 */
	void BroadcastAbilityInfo();

protected:
	/**
	 * 技能信息数据资产
	 * 包含所有技能的图标、名称、描述等 UI 显示数据
	 * 在 Details 面板中指定
	 */
	UPROPERTY(EditDefaultsOnly, BlueprintReadOnly, Category = "Widget Data")
	TObjectPtr<UAbilityInfo> AbilityInfo;

	/** 玩家控制器（基类类型，通过 GetAuraPC 转换为 Aura 专用类型） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<APlayerController> PlayerController;

	/** 玩家状态（基类类型） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<APlayerState> PlayerState;

	/** 能力系统组件（基类类型） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<UAbilitySystemComponent> AbilitySystemComponent;

	/** 属性集（基类类型） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<UAttributeSet> AttributeSet;

	/** Aura 专用玩家控制器（懒加载缓存，通过 GetAuraPC 获取） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<AAuraPlayerController> AuraPlayerController;

	/** Aura 专用玩家状态（懒加载缓存） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<AAuraPlayerState> AuraPlayerState;

	/** Aura 专用能力系统组件（懒加载缓存） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<UAuraAbilitySystemComponent> AuraAbilitySystemComponent;

	/** Aura 专用属性集（懒加载缓存） */
	UPROPERTY(BlueprintReadOnly, Category="WidgetController")
	TObjectPtr<UAuraAttributeSet> AuraAttributeSet;

	/** 懒加载获取 Aura 玩家控制器（Cast<AAuraPlayerController>(PlayerController)） */
	AAuraPlayerController* GetAuraPC();

	/** 懒加载获取 Aura 玩家状态（Cast<AAuraPlayerState>(PlayerState)） */
	AAuraPlayerState* GetAuraPS();

	/** 懒加载获取 Aura 能力系统组件（Cast<UAuraAbilitySystemComponent>(AbilitySystemComponent)） */
	UAuraAbilitySystemComponent* GetAuraASC();

	/** 懒加载获取 Aura 属性集（Cast<UAuraAttributeSet>(AttributeSet)） */
	UAuraAttributeSet* GetAuraAS();
};
"}

{"rawEvent":{"message_id":"019cbbb199bf7c819b045efcd483bbb6","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_B0BzxoUgsgc3OCOVNNmyKY","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/UI/WidgetController/OverlayWidgetController.h","sub_content":"OverlayWidgetController.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/UI/WidgetController/OverlayWidgetController.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/UI/WidgetController/OverlayWidgetController.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "UI/WidgetController/AuraWidgetController.h"
#include "OverlayWidgetController.generated.h"

struct FAuraAbilityInfo;

/**
 * UI 消息 Widget 数据表行结构体
 * 用于 DataTable，通过 GameplayTag 查找对应的消息 Widget 配置
 * 当玩家拾取物品或触发特定事件时，显示对应的消息 Widget
 *
 * 使用示例（DataTable 配置）：
 * 行名：Abilities.Fire.FireBolt
 * MessageTag: Abilities.Fire.FireBolt
 * Message: "获得了火焰箭技能！"
 * MessageWidget: WBP_AbilityPickupMessage
 * Image: T_FireBolt_Icon
 */
USTRUCT(BlueprintType)
struct FUIWidgetRow : public FTableRowBase
{
	GENERATED_BODY()

	/** 触发此消息的 GameplayTag（GE 的 AssetTag，用于在 DataTable 中查找对应行） */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	FGameplayTag MessageTag = FGameplayTag();

	/** 消息文本内容（显示在消息 Widget 上） */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	FText Message = FText();

	/** 消息 Widget 类（用于创建并显示消息 UI） */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	TSubclassOf<class UAuraUserWidget> MessageWidget;

	/** 消息图标（显示在消息 Widget 上，如技能图标或物品图标） */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	UTexture2D* Image = nullptr;
};

class UAuraUserWidget;
class UAbilityInfo;
class UAuraAbilitySystemComponent;

/** 浮点属性变化时广播（生命值、法力值等） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnAttributeChangedSignature, float, NewValue);

/** 玩家等级变化时广播（携带新等级和是否为升级事件） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FOnLevelChangedSignature, int32, NewLevel, bool, bLevelUp);

/** 消息 Widget 行数据广播（拾取物品或触发事件时显示消息） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FMessageWidgetRowSignature, FUIWidgetRow, Row);

/**
 * 主 Overlay HUD 的 Widget 控制器
 *
 * 职责：
 * - 监听 ASC 属性变化（生命值、法力值）并广播给 Widget
 * - 监听 PlayerState 等级/XP 变化并广播给 Widget
 * - 监听 GE 应用事件，通过 DataTable 查找并广播消息 Widget 数据
 * - 监听技能装备事件，更新技能栏显示
 *
 * 广播的委托：
 * - OnHealthChanged / OnMaxHealthChanged：生命值变化（血条更新）
 * - OnManaChanged / OnMaxManaChanged：法力值变化（法力条更新）
 * - MessageWidgetRowDelegate：消息提示（拾取物品等）
 * - OnXPPercentChangedDelegate：XP 百分比变化（经验条更新）
 * - OnPlayerLevelChangedDelegate：等级变化（等级显示更新）
 */
UCLASS(BlueprintType, Blueprintable)
class AURA_API UOverlayWidgetController : public UAuraWidgetController
{
	GENERATED_BODY()
public:
	/**
	 * 广播初始属性值（重写基类）
	 * 广播当前生命值、最大生命值、法力值、最大法力值给 Widget 初始化显示
	 */
	virtual void BroadcastInitialValues() override;

	/**
	 * 绑定回调到依赖项（重写基类）
	 * 绑定 ASC 属性变化、GE 应用、技能装备等事件的回调
	 */
	virtual void BindCallbacksToDependencies() override;

	/** 当前生命值变化时广播（血条 Widget 绑定此委托） */
	UPROPERTY(BlueprintAssignable, Category="GAS|Attributes")
	FOnAttributeChangedSignature OnHealthChanged;

	/** 最大生命值变化时广播（血条 Widget 绑定此委托以更新上限） */
	UPROPERTY(BlueprintAssignable, Category="GAS|Attributes")
	FOnAttributeChangedSignature OnMaxHealthChanged;

	/** 当前法力值变化时广播（法力条 Widget 绑定此委托） */
	UPROPERTY(BlueprintAssignable, Category="GAS|Attributes")
	FOnAttributeChangedSignature OnManaChanged;

	/** 最大法力值变化时广播（法力条 Widget 绑定此委托以更新上限） */
	UPROPERTY(BlueprintAssignable, Category="GAS|Attributes")
	FOnAttributeChangedSignature OnMaxManaChanged;

	/**
	 * 消息 Widget 行数据广播委托
	 * 当 GE 被应用且其 AssetTag 在 MessageWidgetDataTable 中有对应行时广播
	 * Widget 可绑定此委托来显示拾取提示、技能获得提示等
	 */
	UPROPERTY(BlueprintAssignable, Category="GAS|Messages")
	FMessageWidgetRowSignature MessageWidgetRowDelegate;

	/**
	 * XP 百分比变化时广播（经验条 Widget 绑定此委托）
	 * 值为 0.0~1.0，表示当前等级的 XP 进度百分比
	 */
	UPROPERTY(BlueprintAssignable, Category="GAS|XP")
	FOnAttributeChangedSignature OnXPPercentChangedDelegate;

	/**
	 * 玩家等级变化时广播（等级显示 Widget 绑定此委托）
	 * bLevelUp=true 时触发升级特效和音效
	 */
	UPROPERTY(BlueprintAssignable, Category="GAS|Level")
	FOnLevelChangedSignature OnPlayerLevelChangedDelegate;

protected:
	/**
	 * 消息 Widget 数据表
	 * 每行对应一个 GameplayTag，定义触发该 Tag 时显示的消息内容和 Widget 类型
	 * 在 Details 面板中指定
	 */
	UPROPERTY(EditDefaultsOnly, BlueprintReadOnly, Category = "Widget Data")
	TObjectPtr<UDataTable> MessageWidgetDataTable;

	/**
	 * 根据 GameplayTag 从 DataTable 中查找对应的行数据
	 * @tparam T DataTable 行结构体类型
	 * @param DataTable 要查找的数据表
	 * @param Tag 要查找的 GameplayTag（使用 Tag 名称作为行名）
	 * @return 对应行的指针，未找到则返回 nullptr
	 */
	template<typename T>
	T* GetDataTableRowByTag(UDataTable* DataTable, const FGameplayTag& Tag);

	/**
	 * XP 变化回调（绑定到 PlayerState 的 OnXPChangedDelegate）
	 * 计算当前等级的 XP 百分比并广播 OnXPPercentChangedDelegate
	 * @param NewXP 新的 XP 总量
	 */
	void OnXPChanged(int32 NewXP);

	/**
	 * 技能装备回调（绑定到 ASC 的 AbilityEquipped 委托）
	 * 当技能被装备到槽位时，广播技能信息更新技能栏 Widget
	 * @param AbilityTag 已装备的技能标签
	 * @param Status 技能当前状态
	 * @param Slot 新槽位
	 * @param PreviousSlot 原槽位
	 */
	void OnAbilityEquipped(const FGameplayTag& AbilityTag, const FGameplayTag& Status, const FGameplayTag& Slot, const FGameplayTag& PreviousSlot) const;
};

/**
 * 模板函数实现：根据 GameplayTag 从 DataTable 查找行
 * 使用 Tag 的名称（FName）作为 DataTable 的行名进行查找
 */
template <typename T>
T* UOverlayWidgetController::GetDataTableRowByTag(UDataTable* DataTable, const FGameplayTag& Tag)
{
	return DataTable->FindRow<T>(Tag.GetTagName(), TEXT(""));
}
