{"type":"TOOL_CALL_RESULT","timestamp":1772676210,"rawEvent":{"message_id":"019cbbb199bf7c819b045efcd483bbb6","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_bBkGEQmXsrqjKKfC9kePZ0","result":{"commit_id":["d69322f766b3dd9421697dd9b45125efb19c7106","4418a5ef797ad5880208c30283b2a8c420102420"]},"display_name":"编辑文件"},"messageId":"019cbbb199bf7c819b045efcd483bbb6","toolCallId":"tooluse_bBkGEQmXsrqjKKfC9kePZ0","content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "UI/WidgetController/AuraWidgetController.h"
#include "AttributeMenuWidgetController.generated.h"

class UAttributeInfo;
struct FAuraAttributeInfo;
struct FGameplayTag;

/** 属性信息变化时广播（属性菜单 Widget 绑定此委托更新属性显示） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FAttributeInfoSignature, const FAuraAttributeInfo&, Info);

/**
 * 属性菜单 Widget 控制器
 *
 * 职责：
 * - 监听所有主属性（力量、智力、韧性、活力）的变化并广播给 Widget
 * - 处理玩家升级属性的请求（UpgradeAttribute）
 * - 广播属性点数量变化给 Widget
 *
 * 属性信息广播流程：
 * 1. BroadcastInitialValues：遍历所有属性，广播初始值
 * 2. BindCallbacksToDependencies：绑定属性变化回调
 * 3. 属性变化时：调用 BroadcastAttributeInfo 广播新值
 *
 * 使用示例（Widget 中）：
 * // 绑定属性信息委托
 * AttributeMenuWidgetController->AttributeInfoDelegate.AddDynamic(this, &UMyWidget::OnAttributeInfoChanged);
 * // 升级力量属性
 * AttributeMenuWidgetController->UpgradeAttribute(StrengthTag);
 */
UCLASS(BlueprintType, Blueprintable)
class AURA_API UAttributeMenuWidgetController : public UAuraWidgetController
{
	GENERATED_BODY()
public:
	/**
	 * 绑定回调到依赖项（重写基类）
	 * 绑定所有主属性的变化回调，属性变化时广播 AttributeInfoDelegate
	 */
	virtual void BindCallbacksToDependencies() override;

	/**
	 * 广播初始属性值（重写基类）
	 * 遍历 TagsToAttributes 映射，广播每个属性的当前值和描述信息
	 */
	virtual void BroadcastInitialValues() override;

	/**
	 * 属性信息广播委托（蓝图可绑定）
	 * 当任意属性值变化时广播，携带属性的完整信息（名称、描述、当前值）
	 * Widget 绑定此委托来更新属性行的显示
	 */
	UPROPERTY(BlueprintAssignable, Category="GAS|Attributes")
	FAttributeInfoSignature AttributeInfoDelegate;

	/**
	 * 属性点数量变化时广播（蓝图可绑定）
	 * Widget 绑定此委托来更新可用属性点的显示
	 */
	UPROPERTY(BlueprintAssignable, Category="GAS|Attributes")
	FOnPlayerStatChangedSignature AttributePointsChangedDelegate;

	/**
	 * 升级指定属性（蓝图可调用）
	 * 向 ASC 发送升级请求，ASC 转发到服务端 RPC 处理
	 * @param AttributeTag 要升级的属性标签（如 Attributes.Primary.Strength）
	 */
	UFUNCTION(BlueprintCallable)
	void UpgradeAttribute(const FGameplayTag& AttributeTag);

protected:
	/**
	 * 属性信息数据资产
	 * 定义每个属性的显示名称、描述文本等 UI 信息
	 * 在 Details 面板中指定
	 */
	UPROPERTY(EditDefaultsOnly)
	TObjectPtr<UAttributeInfo> AttributeInfo;

private:
	/**
	 * 广播指定属性的信息
	 * 从 AttributeInfo 数据资产中查找属性描述，结合当前属性值，通过 AttributeInfoDelegate 广播
	 * @param AttributeTag 要广播的属性标签
	 * @param Attribute 对应的 FGameplayAttribute 对象（用于获取当前值）
	 */
	void BroadcastAttributeInfo(const FGameplayTag& AttributeTag, const FGameplayAttribute& Attribute) const;
};
"}

{"rawEvent":{"message_id":"019cbbb199bf7c819b045efcd483bbb6","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_QtkO90W2OpPf6qr7nKAIzF","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AI/AuraAIController.h","sub_content":"AuraAIController.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AI/AuraAIController.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AI/AuraAIController.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "AIController.h"
#include "AuraAIController.generated.h"

class UBlackboardComponent;
class UBehaviorTreeComponent;

/**
 * Aura 敌人 AI 控制器
 *
 * 职责：
 * - 持有并管理行为树组件（BehaviorTreeComponent）
 * - 持有黑板组件（BlackboardComponent，由基类 AAIController 提供）
 * - 在构造函数中创建 BehaviorTreeComponent 并设置为默认行为树组件
 *
 * 使用流程：
 * 1. 敌人被 AI 控制器接管（PossessedBy）
 * 2. 敌人调用 RunBehaviorTree(BehaviorTree) 启动行为树
 * 3. 行为树通过黑板（Blackboard）读写 AI 决策数据
 * （如 TargetActor、DistanceToTarget 等）
 *
 * 注意：此控制器只在服务端存在，AI 逻辑不在客户端运行
 */
UCLASS()
class AURA_API AAuraAIController : public AAIController
{
	GENERATED_BODY()
public:
	AAuraAIController();

protected:
	/**
	 * 行为树组件
	 * 负责运行和管理敌人的行为树资产（BehaviorTree）
	 * 在构造函数中创建，通过 RunBehaviorTree 启动
	 */
	UPROPERTY()
	TObjectPtr<UBehaviorTreeComponent> BehaviorTreeComponent;
};
