	int32 CustomDepthStencilOverride = CUSTOM_DEPTH_TAN;

	/**
	 * 蓝图事件：检查点到达时调用
	 * 在蓝图中实现发光特效的启动逻辑（修改材质参数）
	 * @param DynamicMaterialInstance 检查点网格体的动态材质实例
	 */
