#pragma once

#include "CoreMinimal.h"
#include "AbilitySystem/Abilities/AuraDamageGameplayAbility.h"
#include "AuraFireBlast.generated.h"

class AAuraFireBall;

/**
 * 火焰爆炸技能
 *
 * 向四周均匀发射多个火球（AAuraFireBall），火球飞出后返回施法者
 * 去程和回程均可造成伤害，是一个高伤害的范围技能
 *
 * 特性：
 * - 向四周均匀发射 NumFireBalls 个火球（360度均匀分布）
 * - 火球飞出一段距离后自动返回施法者（通过蓝图时间轴控制）
 * - 去程命中敌人造成伤害，回程命中也造成伤害
 * - 升级时增加火球数量和伤害
 *
 * 使用流程：
 * ActivateAbility → SpawnFireBalls → 火球飞出 → 返回 → 结束技能
 */
UCLASS()
class AURA_API UAuraFireBlast : public UAuraDamageGameplayAbility
{
	GENERATED_BODY()
public:
	/**
	 * 获取当前等级的技能描述（重写基类）
	 * 包含：火球数量、伤害值、法力消耗、冷却时间
	 * @param Level 技能等级
	 * @return 格式化的描述字符串
	 */
	virtual FString GetDescription(int32 Level) override;

	/**
	 * 获取下一等级的技能描述（重写基类）
	 * @param Level 当前等级
	 * @return 下一等级的描述字符串
	 */
	virtual FString GetNextLevelDescription(int32 Level) override;

	/**
	 * 生成所有火球（蓝图可调用）
	 * 在施法者周围均匀生成 NumFireBalls 个火球，设置伤害参数后发射
	 * @return 生成的所有火球 Actor 数组（蓝图可用于后续控制，如触发返回）
	 */
	UFUNCTION(BlueprintCallable)
	TArray<AAuraFireBall*> SpawnFireBalls();

protected:
	/**
	 * 火球数量
	 * 每次激活技能时生成的火球数量，均匀分布在 360 度范围内
	 * 默认 12 个
	 */
	UPROPERTY(EditDefaultsOnly, Category = "FireBlast")
	int32 NumFireBalls = 12;

private:
	/**
	 * 火球 Actor 类
	 * 在 Details 面板中指定要生成的火球类型（通常为 BP_AuraFireBall）
	 */
	UPROPERTY(EditDefaultsOnly)
	TSubclassOf<AAuraFireBall> FireBallClass;
};
"}

{"rawEvent":{"message_id":"019cbbc162277a578c80d32e51baaf8e","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_3wKLaA0uevUGghpbrRPOtY","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/Abilities/AuraSummonAbility.h","sub_content":"AuraSummonAbility.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/Abilities/AuraSummonAbility.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/Abilities/AuraSummonAbility.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "AbilitySystem/Abilities/AuraGameplayAbility.h"
#include "AuraSummonAbility.generated.h"

/**
 * 召唤技能基类
 *
 * 用于召唤小兵/随从的技能基类
 * 负责计算召唤位置并随机选择召唤物类型
 *
 * 功能：
 * - 在施法者前方的扇形区域内计算 NumMinions 个均匀分布的生成位置
 * - 生成位置会通过射线检测对齐到地面
 * - 随机从 MinionClasses 数组中选择召唤物类型
 * - 通过 ICombatInterface::IncremenetMinionCount 追踪召唤物数量
 *
 * 使用示例（蓝图中）：
 * // 获取生成位置
 * TArray<FVector> Locations = GetSpawnLocations();
 * // 随机获取召唤物类型
 * TSubclassOf<APawn> MinionClass = GetRandomMinionClass();
 * // 在每个位置生成召唤物
 * for (FVector Loc : Locations) { SpawnActor(MinionClass, Loc); }
 */
UCLASS()
class AURA_API UAuraSummonAbility : public UAuraGameplayAbility
{
	GENERATED_BODY()
public:

	/**
	 * 获取召唤物的生成位置数组（蓝图可调用）
	 * 在施法者前方的扇形区域内计算 NumMinions 个均匀分布的位置
	 * 每个位置通过向下射线检测对齐到地面
	 * @return 世界坐标的生成位置数组（数量等于 NumMinions）
	 */
	UFUNCTION(BlueprintCallable)
	TArray<FVector> GetSpawnLocations();

	/**
	 * 随机获取一个召唤物类（蓝图纯函数）
	 * 从 MinionClasses 数组中随机选择一个类型
	 * @return 随机选中的召唤物 Pawn 类
	 */
	UFUNCTION(BlueprintPure, Category="Summoning")
	TSubclassOf<APawn> GetRandomMinionClass();

	/**
	 * 召唤物数量
	 * 每次激活技能时召唤的小兵数量
	 * 默认 5 个
	 */
	UPROPERTY(EditDefaultsOnly, Category = "Summoning")
	int32 NumMinions = 5;

	/**
	 * 可召唤的小兵类数组
	 * 每次召唤时从此数组中随机选择一个类型
	 * 在 Details 面板中配置（如骷髅战士、骷髅弓箭手等）
	 */
	UPROPERTY(EditDefaultsOnly, Category = "Summoning")
	TArray<TSubclassOf<APawn>> MinionClasses;

	/**
	 * 最小生成距离（单位：cm）
	 * 召唤物生成位置距施法者的最小距离
	 * 默认 50 cm
	 */
	UPROPERTY(EditDefaultsOnly, Category = "Summoning")
	float MinSpawnDistance = 50.f;

	/**
	 * 最大生成距离（单位：cm）
	 * 召唤物生成位置距施法者的最大距离
	 * 默认 250 cm
	 */
	UPROPERTY(EditDefaultsOnly, Category = "Summoning")
	float MaxSpawnDistance = 250.f;

	/**
	 * 生成扩散角度（度）
	 * 召唤物在施法者前方此角度范围内均匀分布
	 * 默认 90 度（左右各 45 度）
	 */
	UPROPERTY(EditDefaultsOnly, Category = "Summoning")
	float SpawnSpread = 90.f;
};
