 * 电击技能（链式闪电）
 *
 * 继承自 UAuraBeamSpell，是闪电系法师的核心技能
 * 向主目标发射闪电光束，并可以链式跳转到附近的其他敌人
 *
 * 特性：
 * - 对主目标持续造成闪电伤害
 * - 闪电可以跳转到主目标附近的最多 MaxNumShockTargets 个敌人
 * - 命中目标有概率触发眩晕 Debuff（Stun）
 * - 升级时增加伤害和跳转目标数量
 *
 * 与 UAuraBeamSpell 的关系：
 * - 继承了所有光束技能的基础逻辑（目标追踪、链式跳转）
 * - 只重写了描述文本函数，其余逻辑在基类中实现
 */
UCLASS()
class AURA_API UElectrocute : public UAuraBeamSpell
{
	GENERATED_BODY()
public:
	/**
	 * 获取当前等级的技能描述（重写基类）
	 * 包含：伤害值、跳转目标数、法力消耗、冷却时间
	 * @param Level 技能等级
	 * @return 格式化的描述字符串
	 */
	virtual FString GetDescription(int32 Level) override;

	/**
	 * 获取下一等级的技能描述（重写基类）
	 * @param Level 当前等级
	 * @return 下一等级的描述字符串
	 */
	virtual FString GetNextLevelDescription(int32 Level) override;
};
"}

{"rawEvent":{"message_id":"019cbbc162277a578c80d32e51baaf8e","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_20exYKHkeajXnNCRSagTW4","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/AbilityTasks/TargetDataUnderMouse.h","sub_content":"TargetDataUnderMouse.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/AbilityTasks/TargetDataUnderMouse.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/AbilitySystem/AbilityTasks/TargetDataUnderMouse.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "Abilities/Tasks/AbilityTask.h"
#include "TargetDataUnderMouse.generated.h"

/** 鼠标目标数据就绪时广播（携带目标数据句柄） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FMouseTargetDataSignature, const FGameplayAbilityTargetDataHandle&, DataHandle);

/**
 * 技能任务：获取鼠标光标下的目标数据
 *
 * 用于需要指定目标位置的技能（如火焰箭、奥术碎片等）
 * 在服务端和客户端之间同步鼠标光标的命中位置
 *
 * 工作原理：
 * - 本地客户端：通过射线检测获取鼠标光标命中位置，打包成 TargetData 发送给服务端
 * - 服务端：等待客户端发送的 TargetData，收到后广播 ValidData 委托
 * - 预测模式：本地客户端立即广播（不等待服务端确认），实现无延迟的本地预测
 *
 * 使用示例（蓝图中）：
 * // 在技能激活时创建此任务
 * UTargetDataUnderMouse* Task = UTargetDataUnderMouse::CreateTargetDataUnderMouse(this);
 * Task->ValidData.AddDynamic(this, &UMyAbility::OnTargetDataReady);
 * Task->ReadyForActivation();
 */
UCLASS()
class AURA_API UTargetDataUnderMouse : public UAbilityTask
{
	GENERATED_BODY()
public:

	/**
	 * 创建鼠标目标数据任务（蓝图可调用，内部使用）
	 * 工厂函数，创建并返回任务实例
	 * @param OwningAbility 拥有此任务的技能实例
	 * @return 创建的任务实例
	 */
	UFUNCTION(BlueprintCallable, Category="Ability|Tasks", meta = (DisplayName = "TargetDataUnderMouse", HidePin = "OwningAbility", DefaultToSelf = "OwningAbility", BlueprintInternalUseOnly = "true"))
	static UTargetDataUnderMouse* CreateTargetDataUnderMouse(UGameplayAbility* OwningAbility);

	/**
	 * 目标数据就绪委托（蓝图可绑定）
	 * 当鼠标目标数据可用时广播（本地预测立即触发，服务端等待客户端数据）
	 * 技能绑定此委托以获取目标位置并执行技能逻辑
	 */
	UPROPERTY(BlueprintAssignable)
	FMouseTargetDataSignature ValidData;

private:
	/**
	 * 任务激活（重写基类）
	 * 本地控制器：调用 SendMouseCursorData 发送目标数据
	 * 非本地控制器（服务端）：等待客户端发送的目标数据
	 */
	virtual void Activate() override;

	/**
	 * 发送鼠标光标目标数据
	 * 通过射线检测获取鼠标光标命中位置，打包成 FGameplayAbilityTargetData_SingleTargetHit
	 * 然后通过 ASC 的 ServerSetReplicatedTargetData 发送给服务端
	 */
	void SendMouseCursorData();

	/**
	 * 目标数据同步回调
	 * 服务端收到客户端发送的目标数据后调用
	 * 广播 ValidData 委托，触发技能的目标处理逻辑
	 * @param DataHandle 收到的目标数据句柄
	 * @param ActivationTag 激活标签（用于标识此次数据传输）
	 */
	void OnTargetDataReplicatedCallback(const FGameplayAbilityTargetDataHandle& DataHandle, FGameplayTag ActivationTag);
};
