{"rawEvent":{"message_id":"019cbbc162277a578c80d32e51baaf8e","conversation_id":"019cbbb02e097afda830766c0bf2426a","tool_call_id":"tooluse_gRIKs94qRm422tVZtoEbTe","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/UI/WidgetController/EnemyHealthBarWidgetController.h","sub_content":"EnemyHealthBarWidgetController.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/UI/WidgetController/EnemyHealthBarWidgetController.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/UI/WidgetController/EnemyHealthBarWidgetController.h","apply_content":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "UI/WidgetController/AuraWidgetController.h"
#include "EnemyHealthBarWidgetController.generated.h"

class AAuraEnemy;

/** 生命值变化时广播（携带新的生命值绝对值） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnHealthChangedSignature, float, NewHealth);

/** 最大生命值变化时广播（携带新的最大生命值） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnMaxHealthChangedSignature, float, NewMaxHealth);

/** 生命值百分比变化时广播（携带 0.0~1.0 的百分比，用于进度条） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnHealthPercentChangedSignature, float, HealthPercent);

/** 敌人名称变化时广播（携带名称文本） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnEnemyNameChangedSignature, FText, EnemyName);

/** 敌人等级变化时广播（携带等级整数） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnEnemyLevelChangedSignature, int32, Level);

/**
 * 敌人头顶血条 Widget 控制器
 *
 * 负责管理敌人头顶显示的生命值条、名称、等级等信息
 * 由 AAuraEnemy 在 BeginPlay 时创建并初始化
 *
 * 职责：
 * - 绑定 ASC 的生命值属性变化回调
 * - 广播生命值、最大生命值、生命值百分比给 Widget
 * - 广播敌人名称和等级给 Widget
 *
 * 与 OverlayWidgetController 的区别：
 * - 此控制器专用于敌人头顶 Widget，不需要 PlayerState
 * - 通过 SetEnemy 设置敌人引用，从敌人获取名称和等级
 * - 每个敌人实例都有独立的控制器实例
 */
UCLASS(BlueprintType, Blueprintable)
class AURA_API UEnemyHealthBarWidgetController : public UAuraWidgetController
{
	GENERATED_BODY()

public:
