	/**
	 * 绑定回调到依赖项（重写基类）
	 * 绑定 ASC 的生命值和最大生命值属性变化回调
	 */
	virtual void BindCallbacksToDependencies() override;

	/**
	 * 设置敌人引用（蓝图可调用）
	 * 从敌人获取名称和等级信息，用于初始广播
	 * @param InEnemy 要关联的敌人 Actor
	 */
