	void SetEnemy(AAuraEnemy* InEnemy);

protected:
	/**
	 * 生命值属性变化回调
	 * 计算生命值百分比并广播 OnHealthChanged 和 OnHealthPercentChanged
	 * @param Data 属性变化数据（包含新值）
