	 */
	virtual bool NetSerialize(FArchive& Ar, class UPackageMap* Map, bool& bOutSuccess);

protected:
	/** 是否被格挡（格挡时伤害减半） */
	UPROPERTY()
	bool bIsBlockedHit = false;

	/** 是否为暴击（暴击时伤害翻倍） */
	UPROPERTY()
	bool bIsCriticalHit = false;

	/** 是否成功触发 Debuff（由 DebuffChance 概率决定） */
	UPROPERTY()
	bool bIsSuccessfulDebuff = false;

	/** Debuff 每次触发的伤害值 */
