	 * Value: 该事件类型的所有处理器数组（类型擦除为 void* 版本）
	 */
	TMap<FName, TArray<TFunction<void(const void*)>>> EventHandlers;

	/** 已发布的事件总数（用于调试统计） */
	UPROPERTY()
	int32 TotalEventsPublished;

	/** 当前活跃的订阅总数（用于调试统计） */
	UPROPERTY()
	int32 TotalSubscriptions;
};
"}

