#### 3. 在 HUD 中创建
```cpp
// AuraHUD.cpp
void AAuraHUD::InitCustomWidget(APlayerController* PC, APlayerState* PS, UAbilitySystemComponent* ASC, UAttributeSet* AS)
{
 checkf(CustomWidgetControllerClass, TEXT("CustomWidgetControllerClass uninitialized"));
 checkf(CustomWidgetClass, TEXT("CustomWidgetClass uninitialized"));

 // 创建 WidgetController
 UMyCustomWidgetController* WidgetController = NewObject<UMyCustomWidgetController>(this, CustomWidgetControllerClass);
 CustomWidgetController = WidgetController;

 // 设置参数
 const FWidgetControllerParams WidgetControllerParams(PC, PS, ASC, AS);
 WidgetController->SetWidgetControllerParams(WidgetControllerParams);
 WidgetController->BindCallbacksToDependencies();

 // 创建 Widget
 UUserWidget* Widget = CreateWidget<UUserWidget>(GetWorld(), CustomWidgetClass);
 CustomWidget = Widget;

 // 设置 WidgetController
 UMyCustomWidget* MyWidget = Cast<UMyCustomWidget>(Widget);
 MyWidget->SetWidgetController(WidgetController);

 // 广播初始值
 WidgetController->BroadcastInitialValues();

 // 添加到视口
 Widget->AddToViewport();
}
```

