class AURA_API UCommandManager : public UGameInstanceSubsystem
{
 GENERATED_BODY()
public:
 void ExecuteCommand(UCommand* Command)
 {
 Command->Execute();
 CommandHistory.Add(Command);
 }

 void Undo()
 {
 if (CommandHistory.Num() > 0)
 {
 UCommand* LastCommand = CommandHistory.Pop();
 LastCommand->Undo();
 }
 }

private:
 UPROPERTY()
