#### 2.3 网络复制优化
**目标**: 减少网络带宽占用

```cpp
// 条件复制
void UAuraAttributeSet::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
 Super::GetLifetimeReplicatedProps(OutLifetimeProps);

 // 只复制给所有者
 DOREPLIFETIME_CONDITION(UAuraAttributeSet, Health, COND_OwnerOnly);
 DOREPLIFETIME_CONDITION(UAuraAttributeSet, Mana, COND_OwnerOnly);

 // 只在变化时复制
 DOREPLIFETIME_CONDITION_NOTIFY(UAuraAttributeSet, MaxHealth, COND_None, REPNOTIFY_OnChanged);
 DOREPLIFETIME_CONDITION_NOTIFY(UAuraAttributeSet, MaxMana, COND_None, REPNOTIFY_OnChanged);
}

// 批量 RPC
UFUNCTION(Server, Reliable)
void ServerBatchUpgradeAttributes(const TArray<FGameplayTag>& AttributeTags);

void UAuraAbilitySystemComponent::ServerBatchUpgradeAttributes_Implementation(const TArray<FGameplayTag>& AttributeTags)
{
 for (const FGameplayTag& Tag : AttributeTags)
 {
 UpgradeAttribute(Tag);
 }
}
```

