{"rawEvent":{"message_id":"019bf2f733fb7f8cb5c4ef4d7c11e947","conversation_id":"01989cf333a379f49bfe098fa68d7b1c","tool_call_id":"tooluse_XmQE_oCnTQ-Wc9HSQ4_-2g","document":{"file_path":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/EventSystem/AuraEventBus.h","sub_content":"AuraEventBus.h","sub_content_event":"open_editor","sub_content_event_value":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/EventSystem/AuraEventBus.h","sub_content_tip":"G:/UE/GameplayAbilitySystem_Aura/Source/Aura/Public/EventSystem/AuraEventBus.h","old_string":"// Copyright Druid Mechanics

#pragma once

#include "CoreMinimal.h"
#include "Subsystems/GameInstanceSubsystem.h"
#include "GameplayTagContainer.h"
#include "EventSystem/AuraEventTypes.h"
#include "AuraEventBus.generated.h"

// 事件处理器委托
DECLARE_DELEGATE_OneParam(FAuraEventHandler, const void*);

/**
 * 事件总线 - 中央事件分发系统
 * 
 * 功能：
 * - 解耦组件间通信
 * - 集中管理事件订阅和发布
 * - 支持C++和蓝图
 * - 自动生命周期管理
 */
UCLASS()
class AURA_API UAuraEventBus : public UGameInstanceSubsystem
{
	GENERATED_BODY()

public:
	// Subsystem 生命周期
	virtual void Initialize(FSubsystemCollectionBase& Collection) override;
	virtual void Deinitialize() override;

	/**
	 * 订阅事件（C++模板方法）
	 * @param Handler 事件处理函数
	 * @return 订阅句柄，用于取消订阅
	 */
	template<typename TEvent>
	FDelegateHandle Subscribe(TFunction<void(const TEvent&)> Handler)
	{
		static_assert(TIsDerivedFrom<TEvent, FAuraEvent>::Value, "TEvent must derive from FAuraEvent");

		const FName EventName = TEvent::StaticStruct()->GetFName();

		if (!EventHandlers.Contains(EventName))
		{
			EventHandlers.Add(EventName, TArray<FAuraEventHandler>());
		}

		// 创建包装器
		FAuraEventHandler Wrapper;
		Wrapper.BindLambda([Handler](const void* Data) {
			Handler(*static_cast<const TEvent*>(Data));
		});

		EventHandlers[EventName].Add(Wrapper);

		// 生成句柄
		FDelegateHandle Handle;
		Handle.Reset();

		UE_LOG(LogTemp, Log, TEXT("[EventBus] Subscribed to event: %s"), *EventName.ToString());

		return Handle;
	}

	/**
	 * 发布事件（C++模板方法）
	 * @param Event 事件数据
	 */
	template<typename TEvent>
	void Publish(const TEvent& Event)
	{
		static_assert(TIsDerivedFrom<TEvent, FAuraEvent>::Value, "TEvent must derive from FAuraEvent");

		const FName EventName = TEvent::StaticStruct()->GetFName();

		if (EventHandlers.Contains(EventName))
		{
			UE_LOG(LogTemp, Verbose, TEXT("[EventBus] Publishing event: %s to %d handlers"), 
				*EventName.ToString(), EventHandlers[EventName].Num());

			for (auto& Handler : EventHandlers[EventName])
			{
				if (Handler.IsBound())
				{
					Handler.Execute(&Event);
				}
			}
		}
		else
		{
			UE_LOG(LogTemp, Verbose, TEXT("[EventBus] No handlers for event: %s"), *EventName.ToString());
		}
	}

	/**
	 * 取消订阅（C++）
	 * @param EventName 事件名称
	 * @param Handle 订阅句柄
	 */
	UFUNCTION(BlueprintCallable, Category = "EventBus")
	void Unsubscribe(FName EventName, FDelegateHandle Handle);

	/**
	 * 清除所有订阅
	 */
	UFUNCTION(BlueprintCallable, Category = "EventBus")
	void ClearAllSubscriptions();

	/**
	 * 获取事件订阅数量
	 */
	UFUNCTION(BlueprintCallable, Category = "EventBus")
	int32 GetSubscriptionCount(FName EventName) const;

	/**
	 * 蓝图：发布属性变化事件
	 */
	UFUNCTION(BlueprintCallable, Category = "EventBus|Events")
	void PublishAttributeChanged(const FAttributeChangedEvent& Event);

	/**
	 * 蓝图：发布技能激活事件
	 */
	UFUNCTION(BlueprintCallable, Category = "EventBus|Events")
