	ENGINE_API UActorComponent* GetComponentByClass(TSubclassOf<UActorComponent> ComponentClass) const;

	/** Templated version of GetComponentByClass */
	template<class T>
	T* GetComponentByClass() const
	{
		return FindComponentByClass<T>();
	}

